package com.multicall.audio;
import android.app.*; import android.os.*; import android.content.*; import android.media.*; import android.widget.*; import android.view.*; import rikka.shizuku.Shizuku;
public class MainActivity extends Activity {
 String selectedPackage; TextView selection; LinearLayout panel,root; TextView status; AudioManager audio;
 int dp(int n){return Math.round(n*getResources().getDisplayMetrics().density);}
 int c(String hex){return android.graphics.Color.parseColor(hex);}
 android.graphics.drawable.GradientDrawable bg(String hex,int radius){android.graphics.drawable.GradientDrawable d=new android.graphics.drawable.GradientDrawable();d.setColor(c(hex));d.setCornerRadius(dp(radius));return d;}
 TextView text(String value,int size,String color){TextView t=new TextView(this);t.setText(value);t.setTextSize(size);t.setTextColor(c(color));t.setPadding(0,dp(4),0,dp(4));return t;}
 void section(String title,String desc){panel=new LinearLayout(this);panel.setOrientation(1);panel.setPadding(dp(18),dp(16),dp(18),dp(16));panel.setBackground(bg("#182338",22));LinearLayout.LayoutParams p=new LinearLayout.LayoutParams(-1,-2);p.topMargin=dp(14);root.addView(panel,p);heading(title);panel.addView(text(desc,13,"#AABBD3"));}
 void heading(String s){TextView t=text(s,23,"#F1F6FF");t.setTypeface(android.graphics.Typeface.DEFAULT_BOLD);panel.addView(t);}
 void button(String s,Runnable r){Button b=new Button(this);b.setText(s);b.setAllCaps(false);b.setTextSize(14);b.setTextColor(c("#D9FDF3"));b.setGravity(Gravity.CENTER_VERTICAL|Gravity.LEFT);b.setPadding(dp(16),dp(8),dp(16),dp(8));b.setBackground(new android.graphics.drawable.RippleDrawable(android.content.res.ColorStateList.valueOf(c("#426B79")),bg("#263B50",14),null));LinearLayout.LayoutParams p=new LinearLayout.LayoutParams(-1,dp(52));p.topMargin=dp(8);panel.addView(b,p);b.setOnClickListener(v->r.run());}
 void launch(String p){Intent i=getPackageManager().getLaunchIntentForPackage(p);if(i!=null)startActivity(i);else status.setText("App not installed or not visible: "+p);}
 void volume(String label,int stream){TextView t=text(label,15,"#E4ECFA");panel.addView(t);SeekBar s=new SeekBar(this);s.setProgressTintList(android.content.res.ColorStateList.valueOf(c("#72F2CE")));s.setThumbTintList(android.content.res.ColorStateList.valueOf(c("#72F2CE")));s.setMax(audio.getStreamMaxVolume(stream));s.setProgress(audio.getStreamVolume(stream));panel.addView(s);s.setOnSeekBarChangeListener(new SeekBar.OnSeekBarChangeListener(){public void onStartTrackingTouch(SeekBar b){} public void onStopTrackingTouch(SeekBar b){} public void onProgressChanged(SeekBar b,int p,boolean user){if(user)try{audio.setStreamVolume(stream,p,0);}catch(Exception e){status.setText(e.toString());}}});}
 @Override public void onCreate(Bundle b){super.onCreate(b);audio=(AudioManager)getSystemService(AUDIO_SERVICE);ScrollView scroll=new ScrollView(this);getWindow().setStatusBarColor(c("#10182A"));getWindow().setNavigationBarColor(c("#10182A"));scroll.setBackgroundColor(c("#10182A"));root=new LinearLayout(this);root.setOrientation(1);root.setPadding(dp(20),dp(24),dp(20),dp(28));scroll.addView(root);setContentView(scroll);panel=root;root.addView(text("MULTICALL  /  AUDIO STUDIO",12,"#72F2CE"));TextView hero=text("Your audio.\\nYour rules.",36,"#F1F6FF");hero.setText("Your audio.\nYour rules.");hero.setTypeface(android.graphics.Typeface.DEFAULT_BOLD);root.addView(hero);root.addView(text("Galaxy edition • Meeting & media control",14,"#AABBD3"));button("Check for updates",()->checkUpdate());section("Connection","System status and command feedback");status=text("Ready • connect Shizuku for advanced controls",14,"#72F2CE");panel.addView(status);section("01  Meeting mode","Keep your meeting open while enjoying media. Enable Multi Sound in Sound Assistant.");volume("Media volume",AudioManager.STREAM_MUSIC);volume("Call stream volume (app dependent)",AudioManager.STREAM_VOICE_CALL);button("Open Samsung Sound Assistant / Multi Sound",()->launch("com.samsung.android.soundassistant"));button("Open Teams",()->launch("com.microsoft.teams"));button("Open Zoom",()->launch("us.zoom.videomeetings"));button("Open Meet",()->launch("com.google.android.apps.meetings"));section("02  App audio control","Choose any installed app. Focus blocking is experimental; use Sound Assistant for per-app volume.");selectedPackage=getPreferences(0).getString("selected",null);selection=text(selectedPackage==null?"No app selected":selectedPackage,15,"#72F2CE");panel.addView(selection);button("Choose installed app",()->chooseApp());button("Connect Shizuku",()->{try{if(!Shizuku.pingBinder()){new AlertDialog.Builder(this).setMessage("Start Shizuku first, then return here.").setPositiveButton("OK",null).show();return;}if(Shizuku.checkSelfPermission()!=0)Shizuku.requestPermission(1);else new AlertDialog.Builder(this).setMessage("Shizuku permission granted.").setPositiveButton("OK",null).show();}catch(Exception e){status.setText(e.toString());}});button("Block selected app audio focus",()->op("ignore"));button("Restore selected app audio focus",()->op("default"));button("Check selected app focus setting",()->op("get"));button("Open selected app",()->{if(selectedPackage!=null)launch(selectedPackage);else status.setText("Select an app first.");});section("Updates","Install new versions without removing MultiCall.");button("Check for updates",()->checkUpdate());section("03  Diagnostics","Check communication mode and troubleshoot audio routing.");button("Check audio mode",()->status.setText("Audio mode: "+audio.getMode()+"; communication mode: "+(audio.getMode()==AudioManager.MODE_IN_COMMUNICATION))); }
 void checkUpdate(){status.setText("Checking for updates…");new Thread(()->{try{String base="https://github.com/rickbesada-netizen/MultiCall/releases/download/android-latest/";java.net.URLConnection conn=new java.net.URL(base+"version.txt").openConnection();conn.setConnectTimeout(15000);conn.setReadTimeout(15000);int latest;try(java.io.BufferedReader r=new java.io.BufferedReader(new java.io.InputStreamReader(conn.getInputStream()))){latest=Integer.parseInt(r.readLine().trim());}int current=getPackageManager().getPackageInfo(getPackageName(),0).versionCode;runOnUiThread(()->{status.setText(latest>current?"Update available":"You have the latest version");if(latest>current)new AlertDialog.Builder(this).setTitle("MultiCall update available").setMessage("Install build "+latest+" over your current app?").setPositiveButton("Download & install",(d,w)->downloadUpdate(base)).setNegativeButton("Later",null).show();else new AlertDialog.Builder(this).setMessage("You have the latest version.").setPositiveButton("OK",null).show();});}catch(Exception e){runOnUiThread(()->new AlertDialog.Builder(this).setMessage("Update check failed: "+e.getMessage()).setPositiveButton("OK",null).show());}}).start();}
 void downloadUpdate(String base){if(!getPackageManager().canRequestPackageInstalls()){startActivity(new Intent(android.provider.Settings.ACTION_MANAGE_UNKNOWN_APP_SOURCES,android.net.Uri.parse("package:"+getPackageName())));new AlertDialog.Builder(this).setMessage("Allow installation from MultiCall, then check for updates again.").setPositiveButton("OK",null).show();return;}ProgressDialog progress=ProgressDialog.show(this,"MultiCall","Downloading update…",true,false);new Thread(()->{try{java.io.File dir=new java.io.File(getCacheDir(),"updates");dir.mkdirs();java.io.File file=new java.io.File(dir,"MultiCall.apk");java.net.URLConnection conn=new java.net.URL(base+"MultiCall.apk").openConnection();conn.setConnectTimeout(15000);conn.setReadTimeout(30000);try(java.io.InputStream in=conn.getInputStream();java.io.FileOutputStream out=new java.io.FileOutputStream(file)){byte[] buf=new byte[16384];int n;while((n=in.read(buf))!=-1)out.write(buf,0,n);}android.content.pm.PackageInfo info=getPackageManager().getPackageArchiveInfo(file.getAbsolutePath(),0);if(info==null||!getPackageName().equals(info.packageName)||info.versionCode<=getPackageManager().getPackageInfo(getPackageName(),0).versionCode)throw new Exception("Invalid or outdated APK");runOnUiThread(()->{progress.dismiss();Intent i=new Intent(Intent.ACTION_VIEW);i.setDataAndType(androidx.core.content.FileProvider.getUriForFile(this,"com.multicall.audio.updates",file),"application/vnd.android.package-archive");i.addFlags(Intent.FLAG_GRANT_READ_URI_PERMISSION);startActivity(i);});}catch(Exception e){runOnUiThread(()->{progress.dismiss();new AlertDialog.Builder(this).setMessage("Download failed: "+e.getMessage()).setPositiveButton("OK",null).show();});}}).start();}
 void chooseApp(){Intent intent=new Intent(Intent.ACTION_MAIN);intent.addCategory(Intent.CATEGORY_LAUNCHER);java.util.List<android.content.pm.ResolveInfo> apps=getPackageManager().queryIntentActivities(intent,0);apps.sort((a,b)->a.loadLabel(getPackageManager()).toString().compareToIgnoreCase(b.loadLabel(getPackageManager()).toString()));String[] names=new String[apps.size()];for(int i=0;i<apps.size();i++)names[i]=apps.get(i).loadLabel(getPackageManager()).toString()+"  •  "+apps.get(i).activityInfo.packageName;new AlertDialog.Builder(this).setTitle("Select an installed app").setItems(names,(d,i)->{selectedPackage=apps.get(i).activityInfo.packageName;selection.setText(names[i]);getPreferences(0).edit().putString("selected",selectedPackage).apply();}).setNegativeButton("Cancel",null).show();}
 void op(String mode){if(selectedPackage==null){new AlertDialog.Builder(this).setMessage("Select an app first.").setPositiveButton("OK",null).show();return;}final String target=selectedPackage;ProgressDialog working=ProgressDialog.show(this,"Audio focus","Checking Shizuku and applying command…",true,false);new Thread(()->{String result;try{if(!Shizuku.pingBinder()||Shizuku.checkSelfPermission()!=0)throw new Exception("Connect and authorize Shizuku first.");java.lang.reflect.Method m=Shizuku.class.getDeclaredMethod("newProcess",String[].class,String[].class,String.class);m.setAccessible(true);String[] cmd=mode.equals("get")?new String[]{"cmd","appops","get",target,"TAKE_AUDIO_FOCUS"}:new String[]{"cmd","appops","set",target,"TAKE_AUDIO_FOCUS",mode};java.lang.Process p=(java.lang.Process)m.invoke(null,cmd,null,null);String out=new String(p.getInputStream().readAllBytes());String err=new String(p.getErrorStream().readAllBytes());int code=p.waitFor();result="Exit "+code+" "+out+" "+err+(code==0?" — test your selected app to verify behavior.":"");}catch(Exception e){result="Unavailable: "+e+"; use Samsung Multi Sound as fallback.";}String r=result;runOnUiThread(()->{working.dismiss();status.setText(r);new AlertDialog.Builder(this).setTitle("Audio focus • "+target).setMessage(r+"\n\nA successful command does not guarantee that Android will stop ducking. Test your music afterward.").setPositiveButton("OK",null).show();});}).start();}
}